css:
/* The farm boy at the twin sunset, a squadron overhead, a nebula for a sky; amber cockpit screens. */

.min-h-screen.surface-fond {
  background-image: linear-gradient(90deg, color-mix(in srgb, var(--surface-fond) 94%, transparent) 0%, color-mix(in srgb, var(--surface-fond) 80%, transparent) 45%, color-mix(in srgb, var(--surface-fond) 25%, transparent) 100%), var(--image-scene), linear-gradient(180deg, #0f0d16 0%, #2b2738 60%, #4a4458 100%);
  background-size: cover, 100vw auto, cover;
  background-position: center, center bottom, center;
  background-repeat: no-repeat;
  background-attachment: fixed;
}

.surface-carte { background-color: color-mix(in srgb, var(--surface-carte) 84%, transparent); }
.surface-carte.border, .rounded-2xl.border { border: 1px solid rgba(255, 122, 26, 0.28); box-shadow: 0 0 18px rgba(255, 122, 26, 0.10); }
[data-app-menubar] { background-color: var(--surface-carte); }
[role="dialog"] { box-shadow: 0 0 0 1px rgba(255, 122, 26, 0.6), 0 0 32px rgba(255, 122, 26, 0.35); }
.surface-carte.border, .rounded-2xl.border { border-top: 2px solid rgba(255, 122, 26, 0.85); }
.surface-menu {
  background-image: repeating-linear-gradient(0deg, rgba(255, 150, 60, 0.05) 0 1px, transparent 1px 3px), linear-gradient(180deg, color-mix(in srgb, var(--surface-menu) 88%, #ffffff), var(--surface-menu));
  border-right: 2px solid #ff7a1a;
}
[data-nav-title] { color: #ffb070; text-transform: uppercase; letter-spacing: 0.18em; font-size: 10px; animation: sw-rebel-crt 5s steps(1) infinite; }
[aria-current="page"] { box-shadow: inset 3px 0 0 #ff7a1a, inset 24px 0 24px -12px rgba(255, 122, 26, 0.3); }
[data-app-menubar] { border-bottom: 1px solid rgba(255, 122, 26, 0.5); }
h1 { text-transform: uppercase; letter-spacing: 0.08em; font-weight: 800; color: var(--color-primary-500); }
@keyframes sw-rebel-crt {
  0%, 100% { text-shadow: 0 0 8px rgba(255, 140, 40, 0.6); }
  48% { text-shadow: 0 0 2px rgba(255, 140, 40, 0.3); }
  50% { text-shadow: 0 0 10px rgba(255, 160, 60, 0.8); }
}
@media (prefers-reduced-motion: reduce) { [data-nav-title] { animation: none; } }
